N=27
grid=[[4]*N for _ in range(N)]
for r in range(N): grid[r][13]=1
for c in range(N): grid[13][c]=1
# TL motif + source base
for r,c,v in [(3,6,5),(4,5,6),(4,6,5),(5,4,3),(6,4,3),(5,5,2),(5,6,2),(6,5,2),(6,6,2),(5,7,1),(5,8,1),(6,7,1),(6,8,1)]: grid[r][c]=v
# target 2-objects
for r in (5,6):
    for c in (20,21): grid[r][c]=2
for r in range(19,23):
    for c in range(4,8): grid[r][c]=2
for r in (20,21):
    for c in (19,20): grid[r][c]=2
# replicate TL motif's non-background/non-anchor cells to TR, scaled 1, horizontal reflection
src={(3,6):5,(4,5):6,(4,6):5,(5,4):3,(6,4):3,(5,7):1,(5,8):1,(6,7):1,(6,8):1}
for (r,c),v in src.items():
    rr=5+(r-5) if r>=5 else r
    cc=20+(1-(c-5))
    grid[rr][cc]=v
# BL: factor 2; vertical flip, no horizontal flip
for (r,c),v in src.items():
    if r>=5: rr=19+2*(r-5)
    else: rr=23+2*(4-r)
    cc=4+2*(c-5)
    for dr in range(2):
        for dc in range(2): grid[rr+dr][cc+dc]=v
# BR: factor 1, flip both axes
for (r,c),v in src.items():
    rr=20+(r-5) if r>=5 else 22+(4-r)
    cc=20-(c-5)
    grid[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))
